// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product, IBeacon, Fixed18, PackedFixed18, PackedUFixed18, UFixed18, IOracleProvider, JumpRateUtilizationCurve, PayoffDefinition, PayoffDefinitionLib, Token18, IProduct, Position, ProgramInfo, ICollateral, IController, IIncentivizer, IMultiInvoker} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;
    MockController controller;
    MockOracle oracle;

    function setUp() public {
        c = new Product();
        controller = new MockController();
        oracle = new MockOracle();
    }

    function testFuzz_property(uint256 newMaintenance) public {
        // create a coordinator owned by this test contract (the product owner)
        uint256 coordinatorId = controller.createCoordinator();

        PayoffDefinition memory pd = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType(0),
            payoffDirection: PayoffDefinitionLib.PayoffDirection(0),
            data: bytes30(0)
        });
        JumpRateUtilizationCurve memory curve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "P",
            symbol: "P",
            payoffDefinition: pd,
            oracle: oracle,
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(type(uint256).max),
            utilizationCurve: curve
        });

        // C records msg.sender as its controller
        vm.prank(address(controller));
        c.initialize(info);

        // bind the product to the coordinator owned by the test contract
        controller.bind(c, coordinatorId);

        // the true coordinator owner calls updateMaintenance
        bool ok;
        vm.prank(address(this));
        try c.updateMaintenance(UFixed18.wrap(newMaintenance)) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: the coordinator owner's update always succeeds and stores
        // exactly the requested maintenance value.
        assertTrue(ok && UFixed18.unwrap(c.maintenance()) == newMaintenance, "owner must be able to update maintenance");
    }
}

contract MockOracle is IOracleProvider {
    function sync() external pure returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function currentVersion() external pure returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function atVersion(uint256) external pure returns (OracleVersion memory) {
        return OracleVersion(0, 0, Fixed18.wrap(0));
    }
}

contract MockController is IController {
    uint256 public nextId = 1;
    mapping(uint256 => address) public coordinatorOwner;
    mapping(address => uint256) public productCoordinator;

    function createCoordinator() external returns (uint256 id) {
        id = nextId++;
        coordinatorOwner[id] = msg.sender;
    }

    function bind(IProduct product, uint256 coordinatorId) external {
        productCoordinator[address(product)] = coordinatorId;
    }

    function owner(uint256 coordinatorId) external view returns (address) {
        return coordinatorOwner[coordinatorId];
    }
    function coordinatorFor(IProduct product) external view returns (uint256) {
        return productCoordinator[address(product)];
